"""Abstract base class and data structures for LLM providers."""

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Optional
import time


@dataclass
class ProviderConfig:
    """Configuration for an LLM provider."""
    api_key: str
    model: str
    max_tokens: int = 4096
    temperature: float = 0.7
    timeout_seconds: int = 120
    base_url: Optional[str] = None

    def __repr__(self) -> str:
        key_display = f"{self.api_key[:4]}...{self.api_key[-4:]}" if len(self.api_key) > 8 else "[REDACTED]"
        return f"ProviderConfig(api_key='{key_display}', model='{self.model}')"


@dataclass
class CompletionResult:
    """Normalized response from any LLM provider."""
    content: str
    model: str
    tokens_in: int
    tokens_out: int
    cost_usd: float
    latency_ms: int
    provider: str
    metadata: dict = field(default_factory=dict)

    @property
    def total_tokens(self) -> int:
        return self.tokens_in + self.tokens_out


class LLMProvider(ABC):
    """Abstract base class for LLM providers."""

    PROVIDER_NAME: str = "base"

    def __init__(self, config: ProviderConfig):
        self.config = config
        self._client = None

    @abstractmethod
    def _init_client(self) -> None:
        """Initialize the provider-specific client."""
        pass

    @abstractmethod
    def complete(self, prompt: str, **kwargs) -> CompletionResult:
        """Generate a completion for the given prompt."""
        pass

    @abstractmethod
    def get_capabilities(self) -> dict:
        """Return provider capabilities (reasoning, code, vision, etc.)."""
        pass

    @abstractmethod
    def get_cost_per_token(self) -> dict:
        """Return cost per 1K tokens for input/output."""
        pass

    def health_check(self) -> bool:
        """Check if provider is available. Default: try a minimal completion."""
        try:
            result = self.complete("Say 'ok'", max_tokens=5)
            return len(result.content) > 0
        except Exception:
            return False

    def _measure_latency(self, func, *args, **kwargs):
        """Wrapper to measure execution time in milliseconds."""
        start = time.perf_counter()
        result = func(*args, **kwargs)
        latency_ms = int((time.perf_counter() - start) * 1000)
        return result, latency_ms

    def _calculate_cost(self, tokens_in: int, tokens_out: int) -> float:
        """Calculate cost in USD based on token counts."""
        costs = self.get_cost_per_token()
        cost_in = (tokens_in / 1000) * costs.get("input", 0)
        cost_out = (tokens_out / 1000) * costs.get("output", 0)
        return round(cost_in + cost_out, 6)

"""Provider factory for easy instantiation from config."""

import json
import os
from pathlib import Path
from typing import Optional

from .provider_interface import LLMProvider, ProviderConfig
from .providers import ClaudeProvider, OpenAIProvider, GeminiProvider, OllamaProvider


PROVIDER_CLASSES = {
    "claude": ClaudeProvider,
    "openai": OpenAIProvider,
    "gemini": GeminiProvider,
    "ollama": OllamaProvider,
}

DEFAULT_CONFIG_PATH = Path(__file__).parent.parent.parent / "data" / "llm-config.json"


def load_config(config_path: Optional[Path] = None) -> dict:
    """Load LLM configuration from JSON file."""
    path = config_path or DEFAULT_CONFIG_PATH
    if not path.exists():
        raise FileNotFoundError(f"LLM config not found: {path}")
    with open(path) as f:
        return json.load(f)


def create_provider(name: str, config: Optional[dict] = None) -> LLMProvider:
    """Create a provider instance by name."""
    if name not in PROVIDER_CLASSES:
        raise ValueError(f"Unknown provider: {name}. Available: {list(PROVIDER_CLASSES.keys())}")

    full_config = load_config() if config is None else config
    provider_config = full_config.get("providers", {}).get(name, {})

    if not provider_config.get("enabled", False):
        raise ValueError(f"Provider '{name}' is disabled in config")

    api_key_env = provider_config.get("api_key_env", "")
    api_key = os.environ.get(api_key_env, "") if api_key_env else ""

    if name != "ollama" and not api_key:
        raise ValueError(f"API key not found for provider '{name}'. Set {api_key_env} env var.")

    model = provider_config.get("default_model")
    if not model:
        raise ValueError(f"No default_model configured for provider '{name}'")

    pconfig = ProviderConfig(
        api_key=api_key,
        model=model,
        max_tokens=provider_config.get("max_tokens", 4096),
        timeout_seconds=provider_config.get("timeout_seconds", 120),
        base_url=provider_config.get("base_url"),
    )

    return PROVIDER_CLASSES[name](pconfig)


def get_default_provider(config: Optional[dict] = None) -> LLMProvider:
    """Get the default provider from config."""
    full_config = config or load_config()
    default_name = full_config.get("default_provider", "claude")
    return create_provider(default_name, full_config)


def get_fallback_chain(config: Optional[dict] = None) -> list[LLMProvider]:
    """Get ordered list of fallback providers."""
    full_config = config or load_config()
    chain = full_config.get("fallback_chain", ["claude"])
    providers = []

    for name in chain:
        try:
            providers.append(create_provider(name, full_config))
        except (ValueError, ImportError):
            continue

    return providers


def complete_with_fallback(prompt: str, config: Optional[dict] = None, **kwargs) -> "CompletionResult":
    """Complete with automatic fallback on failure."""
    from .provider_interface import CompletionResult

    providers = get_fallback_chain(config)
    if not providers:
        raise RuntimeError("No providers available in fallback chain")

    last_error = None
    for provider in providers:
        try:
            return provider.complete(prompt, **kwargs)
        except Exception as e:
            last_error = e
            continue

    raise RuntimeError(f"All providers failed. Last error: {last_error}")

"""
Multi-LLM Client Configuration for Knowledge Extraction Pipeline.
Supports Claude, GPT-4, and Gemini with rate limiting and consensus scoring.
"""

import asyncio
import os
import time
from dataclasses import dataclass, field
from typing import Any, Optional
from abc import ABC, abstractmethod
import json

# Confidence thresholds
CONFIDENCE_THRESHOLDS = {
    "auto_approve": 0.80,
    "review": 0.60,
    "reject": 0.60
}

# Model weights for consensus scoring
MODEL_WEIGHTS = {
    "claude": 0.40,
    "gpt": 0.35,
    "gemini": 0.25,
    "ollama_local": 0.50,  # highest weight when local-first mode is active
}

# Local-first mode: set env KE_LOCAL_FIRST=1 to use Ollama as primary.
LOCAL_FIRST_MODE = os.getenv("KE_LOCAL_FIRST", "0") == "1"
LOCAL_CONFIDENCE_FALLBACK = 0.60  # below this, fall back to cloud


@dataclass
class RateLimiter:
    """Token bucket rate limiter."""
    requests_per_minute: int
    _tokens: float = field(init=False)
    _last_update: float = field(init=False)
    _lock: asyncio.Lock = field(default_factory=asyncio.Lock, init=False)

    def __post_init__(self):
        self._tokens = float(self.requests_per_minute)
        self._last_update = time.monotonic()

    async def acquire(self):
        async with self._lock:
            now = time.monotonic()
            elapsed = now - self._last_update
            self._tokens = min(
                self.requests_per_minute,
                self._tokens + elapsed * (self.requests_per_minute / 60.0)
            )
            self._last_update = now

            if self._tokens < 1:
                wait_time = (1 - self._tokens) * (60.0 / self.requests_per_minute)
                await asyncio.sleep(wait_time)
                self._tokens = 0
            else:
                self._tokens -= 1


@dataclass
class LLMConfig:
    """Configuration for an LLM provider."""
    name: str
    model: str
    api_key_env: str
    max_tokens: int = 4096
    rate_limit_rpm: int = 60
    weight: float = 0.33
    timeout: int = 120

    @property
    def api_key(self) -> Optional[str]:
        return os.getenv(self.api_key_env)


class BaseLLMClient(ABC):
    """Abstract base class for LLM clients."""

    def __init__(self, config: LLMConfig):
        self.config = config
        self.rate_limiter = RateLimiter(config.rate_limit_rpm)

    @abstractmethod
    async def extract(self, prompt: str, source_text: str) -> dict[str, Any]:
        """Extract knowledge from source text using structured prompt."""
        pass

    async def _call_with_retry(self, func, max_retries: int = 3) -> Any:
        """Call function with exponential backoff retry."""
        for attempt in range(max_retries):
            try:
                await self.rate_limiter.acquire()
                return await func()
            except Exception as e:
                if attempt == max_retries - 1:
                    raise
                wait = 2 ** attempt
                await asyncio.sleep(wait)


class ClaudeClient(BaseLLMClient):
    """Anthropic Claude client."""

    async def extract(self, prompt: str, source_text: str) -> dict[str, Any]:
        try:
            from anthropic import AsyncAnthropic
        except ImportError:
            return {"error": "anthropic not installed", "entries": []}

        if not self.config.api_key:
            return {"error": "ANTHROPIC_API_KEY not set", "entries": []}

        client = AsyncAnthropic(api_key=self.config.api_key)

        async def call():
            response = await client.messages.create(
                model=self.config.model,
                max_tokens=self.config.max_tokens,
                messages=[{
                    "role": "user",
                    "content": f"{prompt}\n\n---\nSOURCE TEXT:\n{source_text}"
                }]
            )
            return self._parse_response(response.content[0].text)

        return await self._call_with_retry(call)

    def _parse_response(self, text: str) -> dict[str, Any]:
        try:
            # Try to extract JSON from response
            start = text.find('[')
            end = text.rfind(']') + 1
            if start != -1 and end > start:
                return {"entries": json.loads(text[start:end]), "raw": text}
            return {"entries": [], "raw": text}
        except json.JSONDecodeError:
            return {"entries": [], "raw": text, "parse_error": True}


class GPTClient(BaseLLMClient):
    """OpenAI GPT client."""

    async def extract(self, prompt: str, source_text: str) -> dict[str, Any]:
        try:
            from openai import AsyncOpenAI
        except ImportError:
            return {"error": "openai not installed", "entries": []}

        if not self.config.api_key:
            return {"error": "OPENAI_API_KEY not set", "entries": []}

        client = AsyncOpenAI(api_key=self.config.api_key)

        async def call():
            response = await client.chat.completions.create(
                model=self.config.model,
                max_tokens=self.config.max_tokens,
                messages=[{
                    "role": "user",
                    "content": f"{prompt}\n\n---\nSOURCE TEXT:\n{source_text}"
                }],
                response_format={"type": "json_object"}
            )
            return self._parse_response(response.choices[0].message.content)

        return await self._call_with_retry(call)

    def _parse_response(self, text: str) -> dict[str, Any]:
        try:
            data = json.loads(text)
            entries = data.get("entries", data.get("knowledge_entries", []))
            return {"entries": entries, "raw": text}
        except json.JSONDecodeError:
            return {"entries": [], "raw": text, "parse_error": True}


class GeminiClient(BaseLLMClient):
    """Google Gemini client."""

    async def extract(self, prompt: str, source_text: str) -> dict[str, Any]:
        try:
            import google.generativeai as genai
        except ImportError:
            return {"error": "google-generativeai not installed", "entries": []}

        if not self.config.api_key:
            return {"error": "GOOGLE_API_KEY not set", "entries": []}

        genai.configure(api_key=self.config.api_key)
        model = genai.GenerativeModel(self.config.model)

        async def call():
            response = await asyncio.to_thread(
                model.generate_content,
                f"{prompt}\n\n---\nSOURCE TEXT:\n{source_text}"
            )
            return self._parse_response(response.text)

        return await self._call_with_retry(call)

    def _parse_response(self, text: str) -> dict[str, Any]:
        try:
            start = text.find('[')
            end = text.rfind(']') + 1
            if start != -1 and end > start:
                return {"entries": json.loads(text[start:end]), "raw": text}
            return {"entries": [], "raw": text}
        except json.JSONDecodeError:
            return {"entries": [], "raw": text, "parse_error": True}


class OllamaClient(BaseLLMClient):
    """Local Ollama client. Primary when KE_LOCAL_FIRST=1."""

    DEFAULT_ENDPOINT = "http://localhost:11434/api/chat"

    async def extract(self, prompt: str, source_text: str) -> dict[str, Any]:
        try:
            import httpx
        except ImportError:
            try:
                import urllib.request  # fallback - sync, wrapped in to_thread
                import urllib.error
            except ImportError:
                return {"error": "httpx/urllib not available", "entries": []}

        endpoint = os.getenv("OLLAMA_ENDPOINT", self.DEFAULT_ENDPOINT)

        async def call():
            payload = {
                "model": self.config.model,
                "messages": [
                    {
                        "role": "user",
                        "content": f"{prompt}\n\n---\nSOURCE TEXT:\n{source_text}",
                    }
                ],
                "stream": False,
                "format": "json",
                "options": {"temperature": 0.2, "num_predict": self.config.max_tokens},
            }
            try:
                import httpx
                async with httpx.AsyncClient(timeout=self.config.timeout) as client:
                    r = await client.post(endpoint, json=payload)
                    r.raise_for_status()
                    data = r.json()
                    text = data.get("message", {}).get("content", "")
                    return self._parse_response(text)
            except ImportError:
                # urllib fallback
                import urllib.request
                import json as _json
                req = urllib.request.Request(
                    endpoint,
                    data=_json.dumps(payload).encode("utf-8"),
                    headers={"Content-Type": "application/json"},
                )

                def _sync_call():
                    with urllib.request.urlopen(req, timeout=self.config.timeout) as r:
                        return _json.loads(r.read().decode("utf-8"))

                data = await asyncio.to_thread(_sync_call)
                text = data.get("message", {}).get("content", "")
                return self._parse_response(text)

        return await self._call_with_retry(call)

    def _parse_response(self, text: str) -> dict[str, Any]:
        try:
            # Ollama JSON mode returns a JSON string; may be wrapped in an object
            if not text:
                return {"entries": [], "raw": text}
            # Try bare array first
            start = text.find("[")
            end = text.rfind("]") + 1
            if start != -1 and end > start:
                return {"entries": json.loads(text[start:end]), "raw": text}
            # Otherwise parse as object with 'entries'
            obj = json.loads(text)
            entries = obj.get("entries", obj.get("knowledge_entries", []))
            return {"entries": entries, "raw": text}
        except json.JSONDecodeError:
            return {"entries": [], "raw": text, "parse_error": True}


def _load_local_model_name() -> str:
    """Read persisted local_llm_choice.json; fall back to qwen 7B."""
    try:
        choice_path = os.path.join(os.path.dirname(__file__), "local_llm_choice.json")
        if os.path.exists(choice_path):
            with open(choice_path, "r", encoding="utf-8") as f:
                return json.load(f).get("model", "qwen2.5:7b-instruct-q4_K_M")
    except Exception:
        pass
    return "qwen2.5:7b-instruct-q4_K_M"


# Default configurations
LLM_CONFIGS = {
    "claude": LLMConfig(
        name="claude",
        model="claude-sonnet-4-20250514",
        api_key_env="ANTHROPIC_API_KEY",
        weight=MODEL_WEIGHTS["claude"],
