"""
CoverageTracker — scores how well local knowledge covers a query domain.
Determines whether local reasoning is sufficient or LLM is needed.
"""

import json
import sqlite3
from dataclasses import dataclass
from datetime import datetime, timedelta
from pathlib import Path
from typing import Optional

ROOT = Path(__file__).resolve().parents[4]
VECTORS_DB = ROOT / ".claude" / "data" / "knowledge-distillation" / "decision-vectors.db"
KILL_SIGNALS_PATH = ROOT / ".claude" / "data" / "knowledge-distillation" / "kill-signals.json"


@dataclass
class CoverageResult:
    score: float
    vector_count: int
    signal_count: int
    freshness_penalty: float
    domain: str
    details: dict

    @property
    def level(self) -> str:
        if self.score >= 0.8:
            return "HIGH"
        if self.score >= 0.4:
            return "MEDIUM"
        return "LOW"


class CoverageTracker:
    def __init__(self, db_path: Optional[Path] = None, kill_signals_path: Optional[Path] = None):
        self.db_path = db_path or VECTORS_DB
        self.kill_signals_path = kill_signals_path or KILL_SIGNALS_PATH
        self._conn = None

    @property
    def conn(self):
        if self._conn is None:
            self._conn = sqlite3.connect(str(self.db_path))
            self._conn.row_factory = sqlite3.Row
        return self._conn

    def check(self, query_features: dict) -> CoverageResult:
        industry = query_features.get("industry", "unknown")
        model = query_features.get("business_model", "unknown")
        domain = f"{industry}_{model}"

        vectors = self._count_matching_vectors(query_features)
        signals = self._count_matching_signals(query_features)
        freshness = self._freshness_penalty(query_features)

        raw_score = self._compute_score(vectors, signals, freshness)

        return CoverageResult(
            score=raw_score,
            vector_count=vectors,
            signal_count=signals,
            freshness_penalty=freshness,
            domain=domain,
            details={
                "industry_vectors": self._count_by_field("industry", industry),
                "model_vectors": self._count_by_field("business_model", model),
                "total_vectors": self._total_vectors(),
            },
        )

    def domain_report(self) -> dict:
        rows = self.conn.execute("""
            SELECT
                features_json,
                outcome,
                created_at
            FROM decision_vectors
        """).fetchall()

        domains = {}
        for row in rows:
            features = json.loads(row["features_json"])
            industry = features.get("industry", "unknown")
            model = features.get("business_model", "unknown")
            domain = f"{industry}_{model}"

            if domain not in domains:
                domains[domain] = {"vectors": 0, "failures": 0, "successes": 0, "oldest": None}

            domains[domain]["vectors"] += 1
            if row["outcome"] == "failure":
                domains[domain]["failures"] += 1
            elif row["outcome"] == "success":
                domains[domain]["successes"] += 1

            created = row["created_at"]
            if created and (domains[domain]["oldest"] is None or created < domains[domain]["oldest"]):
                domains[domain]["oldest"] = created

        signals = self._load_kill_signals()
        for domain_key, stats in domains.items():
            v = stats["vectors"]
            s = sum(1 for sig in signals if self._signal_matches_domain(sig, domain_key))
            stats["signals"] = s
            stats["coverage_pct"] = round(self._compute_score(v, s, 0.0) * 100, 1)

        return domains

    def _count_matching_vectors(self, features: dict) -> int:
        industry = features.get("industry", "")
        model = features.get("business_model", "")

        count = 0
        rows = self.conn.execute("SELECT features_json FROM decision_vectors").fetchall()
        for row in rows:
            f = json.loads(row["features_json"])
            if f.get("industry") == industry or f.get("business_model") == model:
                count += 1
        return count

    def _count_matching_signals(self, features: dict) -> int:
        signals = self._load_kill_signals()
        count = 0
        for sig in signals:
            if sig.get("type") == "feature_combo":
                conditions = sig.get("conditions", {})
                match = True
                for key, expected in conditions.items():
                    actual = features.get(key, "")
                    if isinstance(expected, list):
                        if isinstance(actual, list):
                            if not any(a in expected for a in actual):
                                match = False
                        elif actual not in expected:
                            match = False
                    elif actual != expected:
                        match = False
                if match:
                    count += 1
        return count

    def _freshness_penalty(self, features: dict) -> float:
        industry = features.get("industry", "")
        rows = self.conn.execute(
            "SELECT created_at FROM decision_vectors WHERE features_json LIKE ?",
            (f'%"{industry}"%',),
        ).fetchall()

        if not rows:
            return 0.0

        now = datetime.utcnow()
        stale_count = 0
        for row in rows:
            try:
                created = datetime.fromisoformat(row["created_at"])
                if (now - created) > timedelta(days=90):
                    stale_count += 1
            except (ValueError, TypeError):
                pass

        if not rows:
            return 0.0
        return (stale_count / len(rows)) * 0.1

    def _compute_score(self, vectors: int, signals: int, freshness_penalty: float) -> float:
        if vectors >= 20 and signals >= 5:
            score = 1.0
        elif vectors >= 10 and signals >= 3:
            score = 0.7
        elif vectors >= 5:
            score = 0.4
        elif vectors >= 1:
            score = 0.2
        else:
            score = 0.0

        score -= freshness_penalty
        return max(0.0, min(1.0, score))

    def _count_by_field(self, field: str, value: str) -> int:
        rows = self.conn.execute("SELECT features_json FROM decision_vectors").fetchall()
        return sum(1 for r in rows if json.loads(r["features_json"]).get(field) == value)

    def _total_vectors(self) -> int:
        return self.conn.execute("SELECT COUNT(*) FROM decision_vectors").fetchone()[0]

    def _load_kill_signals(self) -> list:
        if not self.kill_signals_path.exists():
            return []
        return json.loads(self.kill_signals_path.read_text(encoding="utf-8"))

    def _signal_matches_domain(self, signal: dict, domain: str) -> bool:
        conditions = signal.get("conditions", {})
        parts = domain.split("_", 1)
        industry = parts[0] if parts else ""
        model = parts[1] if len(parts) > 1 else ""

        for key, vals in conditions.items():
            if key == "industry" and industry:
                if isinstance(vals, list) and industry not in vals:
                    return False
            if key == "business_model" and model:
                if isinstance(vals, list) and model not in vals:
                    return False
        return True

    def close(self):
        if self._conn:
            self._conn.close()
            self._conn = None


if __name__ == "__main__":
    tracker = CoverageTracker()
    report = tracker.domain_report()

    print("=== Domain Coverage Report ===")
    for domain, stats in sorted(report.items(), key=lambda x: x[1]["coverage_pct"], reverse=True):
        print(f"  {domain}: {stats['coverage_pct']}% ({stats['vectors']} vectors, {stats['signals']} signals)")
    tracker.close()

"""
GapDetector — identifies specific knowledge gaps for a query domain.
Produces targeted gaps that can be filled via LLM research.
"""

import json
from dataclasses import dataclass, field
from typing import Optional

from .tracker import CoverageResult


@dataclass
class Gap:
    gap_type: str
    domain: str
    specifics: str
    priority: int
    suggested_query: str

    def to_dict(self) -> dict:
        return {
            "gap_type": self.gap_type,
            "domain": self.domain,
            "specifics": self.specifics,
            "priority": self.priority,
            "suggested_query": self.suggested_query,
        }


class GapDetector:
    GAP_TEMPLATES = {
        "competitor": {
            "priority": 1,
            "query": "List the top 10 competitors for {domain} with URL, pricing, estimated users, and year founded. Include free alternatives.",
        },
        "failure": {
            "priority": 1,
            "query": "What are the top 10 failure patterns for {domain} businesses? Include specific examples with dates, amounts, and root causes.",
        },
        "pricing": {
            "priority": 2,
            "query": "What is the typical pricing range for {domain}? Include free tiers, average subscription price, and willingness-to-pay data.",
        },
        "market_size": {
            "priority": 2,
            "query": "What is the TAM/SAM/SOM for {domain}? Include source, year, and growth rate.",
        },
        "regulatory": {
            "priority": 3,
            "query": "What regulatory barriers exist for {domain}? Include jurisdiction-specific requirements.",
        },
        "success_pattern": {
            "priority": 2,
            "query": "What are the top 5 success patterns for {domain}? Include specific companies, their paths, and key differentiators.",
        },
    }

    def identify_gaps(self, query_features: dict, coverage: CoverageResult) -> list[Gap]:
        gaps = []
        domain = coverage.domain

        if coverage.vector_count < 5:
            gaps.append(Gap(
                gap_type="competitor",
                domain=domain,
                specifics=f"Only {coverage.vector_count} vectors for {domain}",
                priority=1,
                suggested_query=self.GAP_TEMPLATES["competitor"]["query"].format(domain=domain),
            ))

        details = coverage.details
        if details.get("industry_vectors", 0) < 3:
            industry = query_features.get("industry", "unknown")
            gaps.append(Gap(
                gap_type="failure",
                domain=domain,
                specifics=f"No failure patterns for industry={industry}",
                priority=1,
                suggested_query=self.GAP_TEMPLATES["failure"]["query"].format(domain=industry),
            ))

        if coverage.signal_count < 2:
            gaps.append(Gap(
                gap_type="failure",
                domain=domain,
                specifics=f"Only {coverage.signal_count} kill signals for {domain}",
                priority=1,
                suggested_query=self.GAP_TEMPLATES["failure"]["query"].format(domain=domain),
            ))

        if coverage.score < 0.7:
            gaps.append(Gap(
                gap_type="market_size",
                domain=domain,
                specifics=f"No market size data for {domain}",
                priority=2,
                suggested_query=self.GAP_TEMPLATES["market_size"]["query"].format(domain=domain),
            ))

            gaps.append(Gap(
                gap_type="pricing",
                domain=domain,
                specifics=f"No pricing intelligence for {domain}",
                priority=2,
                suggested_query=self.GAP_TEMPLATES["pricing"]["query"].format(domain=domain),
            ))

        if coverage.score < 0.4:
            gaps.append(Gap(
                gap_type="success_pattern",
                domain=domain,
                specifics=f"Novel domain {domain}, no success patterns",
                priority=2,
                suggested_query=self.GAP_TEMPLATES["success_pattern"]["query"].format(domain=domain),
            ))

        if coverage.freshness_penalty > 0.05:
            gaps.append(Gap(
                gap_type="staleness",
                domain=domain,
                specifics=f"Freshness penalty {coverage.freshness_penalty:.2f} — stale facts",
                priority=3,
                suggested_query=f"What has changed in {domain} in the last 90 days? New entrants, policy changes, market shifts.",
            ))

        return sorted(gaps, key=lambda g: g.priority)

